import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    n = int(data[0])
    a = []
    for k in range(n):
        a.append(int(data[1 + k]))

    # Function f(x) counts the number of set bits (1s) in the binary representation of x
    # f(0) = 0
    # f(2*x) = f(x)  -> shifting left doesn't change bit count
    # f(2*x + 1) = f(x) + 1 -> adding 1 at the end adds one bit
    # This is exactly the population count (popcount)

    counts = {}
    for x in a:
        # Count set bits
        # Python's bin(x) returns string like '0b101', slice off '0b' and count '1's
        cnt = bin(x).count('1')

        if cnt in counts:
            counts[cnt] += 1
        else:
            counts[cnt] = 1

    total_pairs = 0
    for count in counts.values():
        if count > 1:
            # Number of pairs from 'count' items is count * (count - 1) / 2
            total_pairs += count * (count - 1) // 2

    print(total_pairs)

if __name__ == "__main__":
    solve()

